const body = $input.first().json.body ?? {};
const tema = String(body.tema ?? "").trim();
if (!tema) throw new Error("O campo tema e obrigatorio.");
const modos = ["gerar_do_zero", "pesquisar", "chat"];
const modo = modos.includes(body.modo) ? body.modo : "gerar_do_zero";
return [{ json: {
  tema,
  modo,
  origem: body.origem ?? null,
  user_id: body.user_id ?? null,
  mensagem_usuario: body.mensagem_usuario ?? null,
  conteudo_atual: body.conteudo_atual ?? null,
} }];

const entrada = $("Validar entrada").first().json;

// So o ramo "pesquisar" passa pelo no de curadoria. Referenciar um no que nao rodou lanca,
// entao o try/catch e o que distingue "nao pesquisou" de "pesquisou e nao achou".
let curadoria = { encontrou: false, topicos: [], referencias: [] };
try {
  const c = $("Buscar curadoria").first().json;
  if (c && typeof c === "object") curadoria = c;
} catch (e) { /* ramo sem pesquisa */ }

const FORMATO = "Responda APENAS um JSON valido com as chaves: titulo (string), legenda (string), gancho (string, a primeira frase que prende), cta (string), hashtags (array de strings sem #), roteiro (array de 3 a 6 strings, cada uma um slide do carrossel).";
const SISTEMA = "Voce e redator de conteudo para Instagram, em portugues do Brasil. " + FORMATO;

let usuario;
if (entrada.modo === "chat") {
  usuario = [
    "Refine o conteudo abaixo conforme o pedido. Mantenha o mesmo tema e o mesmo formato de JSON.",
    "",
    "TEMA: " + entrada.tema,
    "PEDIDO: " + (entrada.mensagem_usuario ?? ""),
    "",
    "CONTEUDO ATUAL:",
    JSON.stringify(entrada.conteudo_atual ?? {}, null, 2),
  ].join("\n");
} else if (curadoria.encontrou) {
  const refs = (curadoria.referencias ?? []).map(function (r, i) {
    return [
      (i + 1) + ") @" + r.perfil + " (" + (r.formato ?? "post") + ", " + (r.grupo ?? "sem grupo") + ")",
      "   assunto: " + (r.temaDetectado ?? "-"),
      "   categoria/funil: " + (r.categoria ?? "-") + " / " + (r.funil ?? "-"),
      "   resumo: " + (r.resumo ?? "-"),
    ].join("\n");
  }).join("\n");
  const topicos = (curadoria.topicos ?? []).map(function (t) {
    return t.label + (t.tendencia ? " (" + t.tendencia.mencoes7d + " mencoes em 7d)" : "");
  }).join(", ");
  usuario = [
    "Crie um conteudo NOVO sobre o tema: " + entrada.tema,
    "",
    "Use as referencias abaixo como INSPIRACAO de angulo, estrutura e tom. NAO copie: nada de",
    "reaproveitar frases, e o conteudo precisa ser original e sobre o tema pedido.",
    "",
    "TOPICOS EM ALTA NA CURADORIA: " + (topicos || "-"),
    "",
    "REFERENCIAS:",
    refs,
  ].join("\n");
} else {
  usuario = "Crie um conteudo original sobre o tema: " + entrada.tema;
}

return [{ json: {
  curadoria,
  corpoIA: {
    model: "gpt-4o-mini",
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: SISTEMA },
      { role: "user", content: usuario },
    ],
  },
} }];

const entrada = $("Validar entrada").first().json;
const curadoria = $("Montar prompt").first().json.curadoria ?? { encontrou: false, referencias: [] };

let gerado = {};
try {
  gerado = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error("A IA devolveu um JSON invalido: " + e.message);
}

const usouCuradoria = entrada.modo === "pesquisar" && curadoria.encontrou === true;
const precisaExterna = entrada.modo === "pesquisar" && !usouCuradoria;

const referencias = usouCuradoria
  ? (curadoria.referencias ?? []).map(function (r) {
      return {
        perfil: "@" + r.perfil,
        post_id: r.postId,
        tema_detectado: r.temaDetectado ?? "",
        resumo: r.resumo ?? "",
      };
    })
  : [];

let mensagem;
if (entrada.modo === "chat") mensagem = "Conteudo atualizado conforme o pedido.";
else if (usouCuradoria) mensagem = "Gerado a partir de " + referencias.length + " post(s) da curadoria.";
else if (precisaExterna) mensagem = "Tema nao encontrado na curadoria. Pesquisa externa sera usada.";
else mensagem = "Gerado do zero a partir do tema.";

return [{ json: {
  ok: true,
  modo: entrada.modo,
  tema: entrada.tema,
  usou_curadoria: usouCuradoria,
  needs_external_research: precisaExterna,
  referencias,
  conteudo: {
    titulo: gerado.titulo ?? "",
    legenda: gerado.legenda ?? "",
    gancho: gerado.gancho ?? "",
    cta: gerado.cta ?? "",
    hashtags: Array.isArray(gerado.hashtags) ? gerado.hashtags : [],
    roteiro: Array.isArray(gerado.roteiro) ? gerado.roteiro : [],
  },
  mensagem,
} }];
